begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or raise_exception or check_violation or invalid_parameter_value then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('f6000000-0000-4000-8000-000000000001','growth-buyer@synthetic.invalid',now(),'{}'),('f6000000-0000-4000-8000-000000000002','growth-supplier@synthetic.invalid',now(),'{}'),('f6000000-0000-4000-8000-000000000003','growth-other@synthetic.invalid',now(),'{}');
update public.user_roles set role='supplier' where user_id='f6000000-0000-4000-8000-000000000002';
insert into public.businesses(id,owner_id,name,division,district) values('f7000000-0000-4000-8000-000000000001','f6000000-0000-4000-8000-000000000002','Synthetic Growth Supplier','Dhaka','Dhaka');
set local role authenticated;set local request.jwt.claims='{"sub":"f6000000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.search_history('record','synthetic cotton');
select pg_temp.ok(public.search_history()->>0='synthetic cotton','private search history saved');
select public.buyer_organization_save(0,'{"name":"Synthetic Retailers","business_type":"retailer","trade_license_number":"0000123","address":"Synthetic address"}');
select pg_temp.ok(public.buyer_organization_get()->>'trade_license_number'='0000123','text identifiers preserved');
select pg_temp.denied($$select public.shipping_preset_save('f7000000-0000-4000-8000-000000000001',0,'{}')$$);
set local request.jwt.claims='{"sub":"f6000000-0000-4000-8000-000000000003","role":"authenticated"}';
select pg_temp.ok(public.search_history()='[]'::jsonb,'other accounts cannot read search history');
select pg_temp.denied($$select public.buyer_organization_context('f6000000-0000-4000-8000-000000000001')$$);
select pg_temp.ok((select count(*)=0 from public.buyer_organizations),'buyer organizations private');
set local request.jwt.claims='{"sub":"f6000000-0000-4000-8000-000000000002","role":"authenticated"}';
select public.shipping_preset_save('f7000000-0000-4000-8000-000000000001',0,'{"enabled":true,"inside_dhaka_base":100,"outside_dhaka_base":200,"per_kg_surcharge":20,"free_shipping_threshold":20000,"carrier_preference":"self"}');
select pg_temp.ok(public.public_shipping_presets('f7000000-0000-4000-8000-000000000001') is null,'no listings means no public shipping data');
select pg_temp.denied($$select public.supplier_bulk_products('[{"id":"f7000000-0000-4000-8000-000000000001"}]')$$);
select pg_temp.ok(public.supplier_performance()->>'orders'='0','performance uses real counts');
select public.supplier_bulk_products(jsonb_build_array(jsonb_build_object('name','Synthetic imported product','name_bn','','description','Synthetic import rolled back','category_id',(select id from public.categories limit 1),'price',100,'moq',5,'stock',20,'unit','piece','specifications','{}'::jsonb,'tiers','[]'::jsonb)));
select pg_temp.ok((select count(*)=1 from public.products where business_id='f7000000-0000-4000-8000-000000000001' and status='pending'),'bulk import creates moderated listings');
select pg_temp.ok(public.public_shipping_presets('f7000000-0000-4000-8000-000000000001') is null,'pending imports do not expose shipping data');

reset role;set local role anon;
select pg_temp.denied('select public.buyer_organization_get()');
select pg_temp.ok(jsonb_typeof(public.catalog_facets()->'categories')='object','public facet shape');
reset role;
select 'Growth authorization, profiles, shipping and facet checks passed' result;
rollback;
